    ffi.Pointer<ffi.Void>,
    ffi.Pointer<ffi.Char>,
    nutrient_toolbar_tap_callback,
  )
>()
external void nutrient_set_main_toolbar_items(
  ffi.Pointer<ffi.Void> viewController,
  ffi.Pointer<ffi.Char> itemsJson,
  nutrient_toolbar_tap_callback callback,
);

/// Tears down the automatic file-conflict resolution observer registered by
