    1 => PSPDFActionTypeGoTo,
    2 => PSPDFActionTypeRemoteGoTo,
    3 => PSPDFActionTypeNamed,
    4 => PSPDFActionTypeLaunch,
    5 => PSPDFActionTypeJavaScript,
    6 => PSPDFActionTypeRendition,
    7 => PSPDFActionTypeRichMediaExecute,
    8 => PSPDFActionTypeSubmitForm,
    9 => PSPDFActionTypeResetForm,
    10 => PSPDFActionTypeSound,
    11 => PSPDFActionTypeMovie,
    12 => PSPDFActionTypeHide,
    13 => PSPDFActionTypeThread,
    14 => PSPDFActionTypeImportData,
    15 => PSPDFActionTypeSetOCGState,
    16 => PSPDFActionTypeTrans,
    17 => PSPDFActionTypeGoTo3DView,
    18 => PSPDFActionTypeGoToEmbedded,
