/// The types of author-specific state that may be associated with an annotation.
/// States are grouped into categories defined by `PSPDFAnnotationAuthorStateModel`.
/// See the Annotation States section in the PDF specification.
enum PSPDFAnnotationAuthorState {
  /// The value when `PSPDFAnnotationAuthorStateModel` is `PSPDFAnnotationAuthorStateModelUnspecified`. Think of this as nil.
  PSPDFAnnotationAuthorStateUnspecified(0),

  /// The annotation has been marked by the user.
  PSPDFAnnotationAuthorStateMarked(1),

  /// The annotation has not been marked by the user (the default for `PSPDFAnnotationAuthorStateModelMarked`).
  PSPDFAnnotationAuthorStateUnmarked(2),

  /// The user agrees with the change.
  PSPDFAnnotationAuthorStateAccepted(3),

  /// The user disagrees with the change.
  PSPDFAnnotationAuthorStateRejected(4),

  /// The change has been cancelled.
  PSPDFAnnotationAuthorStateCancelled(5),

  /// The change has been completed.
  PSPDFAnnotationAuthorStateCompleted(6),

  /// The user has indicated nothing about the change (the default for `PSPDFAnnotationAuthorStateModelReview`).
  PSPDFAnnotationAuthorStateNone(7);

  final int value;
  const PSPDFAnnotationAuthorState(this.value);

  static PSPDFAnnotationAuthorState fromValue(int value) => switch (value) {
    0 => PSPDFAnnotationAuthorStateUnspecified,
    1 => PSPDFAnnotationAuthorStateMarked,
    2 => PSPDFAnnotationAuthorStateUnmarked,
    3 => PSPDFAnnotationAuthorStateAccepted,
    4 => PSPDFAnnotationAuthorStateRejected,
    5 => PSPDFAnnotationAuthorStateCancelled,
    6 => PSPDFAnnotationAuthorStateCompleted,
    7 => PSPDFAnnotationAuthorStateNone,
    _ => throw ArgumentError(
      'Unknown value for PSPDFAnnotationAuthorState: $value',
    ),
  };
}

/// Categories for the author-specific state that may be associated with an annotation.
enum PSPDFAnnotationAuthorStateModel {
  /// The annotation is not a state annotation. Think of this as nil.
  PSPDFAnnotationAuthorStateModelUnspecified(0),

  /// Specifies that the state is a marked state.
  PSPDFAnnotationAuthorStateModelMarked(1),

  /// Specifies that the state is a review state.
  PSPDFAnnotationAuthorStateModelReview(2);

  final int value;
  const PSPDFAnnotationAuthorStateModel(this.value);

  static PSPDFAnnotationAuthorStateModel fromValue(int value) =>
      switch (value) {
        0 => PSPDFAnnotationAuthorStateModelUnspecified,
        1 => PSPDFAnnotationAuthorStateModelMarked,
        2 => PSPDFAnnotationAuthorStateModelReview,
        _ => throw ArgumentError(
          'Unknown value for PSPDFAnnotationAuthorStateModel: $value',
        ),
      };
}

/// Border effect names. See PDF Reference 1.5, 1.6. (Table 167).
