    2 => PSPDFAnnotationBorderStyleDashed,
    3 => PSPDFAnnotationBorderStyleBeveled,
    4 => PSPDFAnnotationBorderStyleInset,
    5 => PSPDFAnnotationBorderStyleUnderline,
    6 => PSPDFAnnotationBorderStyleUnknown,
