/// Annotations can be saved in the PDF or alongside in an external file.
enum PSPDFAnnotationSaveMode {
  /// Saving will be disabled. When this setting is used, annotation editing UI will be disabled.
  /// Otherwise there would be data loss because the user could make edits that would then not be saved.
  PSPDFAnnotationSaveModeDisabled(0),

  /// Will save to an external file. Uses `save/loadAnnotationsWithError:` in `PSPDFAnnotationManager`.
  PSPDFAnnotationSaveModeExternalFile(1),

  /// Will only save directly into the PDF.
  PSPDFAnnotationSaveModeEmbedded(2),

  /// Tries to save into the PDF if the file is writable, else falls back to external file.
  PSPDFAnnotationSaveModeEmbeddedWithExternalFileAsFallback(3);

  final int value;
  const PSPDFAnnotationSaveMode(this.value);

  static PSPDFAnnotationSaveMode fromValue(int value) => switch (value) {
    0 => PSPDFAnnotationSaveModeDisabled,
    1 => PSPDFAnnotationSaveModeExternalFile,
    2 => PSPDFAnnotationSaveModeEmbedded,
    3 => PSPDFAnnotationSaveModeEmbeddedWithExternalFileAsFallback,
    _ => throw ArgumentError(
      'Unknown value for PSPDFAnnotationSaveMode: $value',
    ),
  };
}

