/// Trigger events for certain viewer actions. See PDF Reference 1.7, 423ff.
enum PSPDFAnnotationTriggerEvent {
  /// Cursor Enters. (Unsupported) E (0)
  PSPDFAnnotationTriggerEventCursorEnters(0),

  /// Cursor Exits. (Unsupported) X  (1)
  PSPDFAnnotationTriggerEventCursorExits(1),

  /// Triggered on `touchesBegan:` D  (2)
  PSPDFAnnotationTriggerEventMouseDown(2),

  /// Triggered on `touchesEnded:` U  (3)
  PSPDFAnnotationTriggerEventMouseUp(3),

  /// Triggers when the annotation is tapped. Fo (4)
  PSPDFAnnotationTriggerEventReceiveFocus(4),

  /// Triggers when the annotation is tapped. Bl (5)
  PSPDFAnnotationTriggerEventLoseFocus(5),

  /// Page opens. (Unsupported) PO (6)
  PSPDFAnnotationTriggerEventPageOpened(6),

  /// Page closes. (Unsupported) PC (7)
  PSPDFAnnotationTriggerEventPageClosed(7),

  /// Page becomes visible. (Unsupported) PV (8)
  PSPDFAnnotationTriggerEventPageVisible(8),

  /// Form value changes. K  (9)
  PSPDFAnnotationTriggerEventFormChanged(9),

  /// Form is formatted. F (10)
  PSPDFAnnotationTriggerEventFieldFormat(10),

  /// Form is validated. V (11)
  PSPDFAnnotationTriggerEventFormValidate(11),

  /// Form is calculated. C (12)
  PSPDFAnnotationTriggerEventFormCalculate(12);

  final int value;
  const PSPDFAnnotationTriggerEvent(this.value);

  static PSPDFAnnotationTriggerEvent fromValue(int value) => switch (value) {
    0 => PSPDFAnnotationTriggerEventCursorEnters,
    1 => PSPDFAnnotationTriggerEventCursorExits,
    2 => PSPDFAnnotationTriggerEventMouseDown,
    3 => PSPDFAnnotationTriggerEventMouseUp,
    4 => PSPDFAnnotationTriggerEventReceiveFocus,
    5 => PSPDFAnnotationTriggerEventLoseFocus,
    6 => PSPDFAnnotationTriggerEventPageOpened,
    7 => PSPDFAnnotationTriggerEventPageClosed,
    8 => PSPDFAnnotationTriggerEventPageVisible,
    9 => PSPDFAnnotationTriggerEventFormChanged,
    10 => PSPDFAnnotationTriggerEventFieldFormat,
    11 => PSPDFAnnotationTriggerEventFormValidate,
    12 => PSPDFAnnotationTriggerEventFormCalculate,
    _ => throw ArgumentError(
      'Unknown value for PSPDFAnnotationTriggerEvent: $value',
    ),
  };
}

