/// A trigger for a document to be automatically saved.
enum PSPDFAutosaveReason {
  /// Called when the view controller was visible but is being dismissed/is disappearing because of another presentation. (`viewDidDisappear`)
  PSPDFAutosaveReasonDisappearing(0),

  /// The application is moved to background (see `UIApplicationDidEnterBackgroundNotification`)
  PSPDFAutosaveReasonMovingToBackground(1),

  /// The application is terminating. (see `UIApplicationWillTerminateNotification`)
  PSPDFAutosaveReasonTerminating(2),

  /// A file conflict has been detected and is being resolved. See ``PSPDFKit/PSPDFFileConflictResolution``.
  PSPDFAutosaveReasonResolvingFileConflict(3),

  /// The window scene did disconnect (the user closed the window).
  PSPDFAutosaveReasonSceneDisconnecting(4);

  final int value;
  const PSPDFAutosaveReason(this.value);

  static PSPDFAutosaveReason fromValue(int value) => switch (value) {
    0 => PSPDFAutosaveReasonDisappearing,
    1 => PSPDFAutosaveReasonMovingToBackground,
    2 => PSPDFAutosaveReasonTerminating,
    3 => PSPDFAutosaveReasonResolvingFileConflict,
    4 => PSPDFAutosaveReasonSceneDisconnecting,
    _ => throw ArgumentError('Unknown value for PSPDFAutosaveReason: $value'),
  };
}

