  /// Images used are: `bookmark-large-color`, `bookmark-large-shadow`
  PSPDFBookmarkIndicatorImageTypeLarge(0),

  /// Specifies the medium (11pt x 18pt) bookmark image.
  ///
  /// Images used are: `bookmark-medium-color`, `bookmark-medium-shadow`
  PSPDFBookmarkIndicatorImageTypeMedium(1),

  /// Specifies the small (7pt x 12pt) bookmark image.
  ///
  /// Images used are: `bookmark-small-color`, `bookmark-small-shadow`
  PSPDFBookmarkIndicatorImageTypeSmall(2);

  final int value;
  const PSPDFBookmarkIndicatorImageType(this.value);

  static PSPDFBookmarkIndicatorImageType fromValue(int value) =>
      switch (value) {
        0 => PSPDFBookmarkIndicatorImageTypeLarge,
        1 => PSPDFBookmarkIndicatorImageTypeMedium,
        2 => PSPDFBookmarkIndicatorImageTypeSmall,
        _ => throw ArgumentError(
          'Unknown value for PSPDFBookmarkIndicatorImageType: $value',
        ),
      };
}

/// The `BookmarkManager` manages bookmarks for a given `Document`.
///
/// You should not initialize a bookmark manager yourself but instead access it through
/// the document's `bookmarkManager` property.
///
/// ### Bookmarks and PDF files
///
/// The concept of bookmarks does not exist in a PDF document. Therefore all the bookmarks
/// you add will be stored inside the PDF but are only read by Nutrient and Apple Preview.
/// If you want to support other formats, you need to create your own bookmark provider
/// and store them yourself.
///
/// ### Subclassing
