/// Defines the state of controller, depending on the document.
enum PSPDFControllerState {
  /// No data is set or no data could be loaded.
  PSPDFControllerStateEmpty(0),

  /// Controller is querying data.
  PSPDFControllerStateLoading(1),

  /// Data is set. This is the state we want.
  PSPDFControllerStateDefault(2),

  /// Data is invalid.
  PSPDFControllerStateError(3),

  /// The data currently is locked.
  PSPDFControllerStateLocked(4);

  final int value;
  const PSPDFControllerState(this.value);

  static PSPDFControllerState fromValue(int value) => switch (value) {
    0 => PSPDFControllerStateEmpty,
    1 => PSPDFControllerStateLoading,
    2 => PSPDFControllerStateDefault,
    3 => PSPDFControllerStateError,
    4 => PSPDFControllerStateLocked,
    _ => throw ArgumentError('Unknown value for PSPDFControllerState: $value'),
  };
}

