  /// Optimizes the file size and rewrites the file. This is the slowest option of the three, but it offers the smallest file size. If you need to optimize for saving performance, use `PSPDFDocumentSaveStrategyAppend` instead.
  PSPDFDocumentSaveStrategyRewriteAndOptimizeFileSize(2);

  final int value;
  const PSPDFDocumentSaveStrategy(this.value);

  static PSPDFDocumentSaveStrategy fromValue(int value) => switch (value) {
    0 => PSPDFDocumentSaveStrategyAppend,
    1 => PSPDFDocumentSaveStrategyRewrite,
    2 => PSPDFDocumentSaveStrategyRewriteAndOptimizeFileSize,
    _ => throw ArgumentError(
      'Unknown value for PSPDFDocumentSaveStrategy: $value',
    ),
  };
}

