/// Defines how annotations, which are drawn, are created.
///
/// The equivalent API in Nutrient Android SDK is [`AnnotationAggregationStrategy`](/api/android/kdoc/pspdfkit/com.pspdfkit.configuration.annotations/-annotation-aggregation-strategy/).
enum PSPDFDrawCreateMode {
  /// Every stroke will result in a separate ink annotation.
  /// This creates the maximum number of annotations.
  PSPDFDrawCreateModeSeparate(0),

  /// Strokes that have the same color/width are merged.
  /// This creates the minimum number of annotations.
  PSPDFDrawCreateModeMergeIfPossible(1),

  /// Stokes that are drawn close together without too much delay are merged.
  /// This is the default.
  PSPDFDrawCreateModeAutomatic(2);

  final int value;
  const PSPDFDrawCreateMode(this.value);

  static PSPDFDrawCreateMode fromValue(int value) => switch (value) {
    0 => PSPDFDrawCreateModeSeparate,
    1 => PSPDFDrawCreateModeMergeIfPossible,
    2 => PSPDFDrawCreateModeAutomatic,
    _ => throw ArgumentError('Unknown value for PSPDFDrawCreateMode: $value'),
  };
}

/// The different kinds of input methods we support for creating a handwritten signature.
enum PSPDFDrawInputMethod {
  /// The signature input mode is not stored.
  PSPDFDrawInputMethodNone(0),

  /// The signature was created using the finger.
  PSPDFDrawInputMethodFinger(1),

  /// The signature was created using an Apple Pencil.
  PSPDFDrawInputMethodApplePencil(2),

  /// The signature was created using a third-party stylus.
  PSPDFDrawInputMethodThirdPartyStylus(3),

  /// The signature was created using a mouse. Although not used by Nutrient for now, other platforms might create biometric data with this input method.
  PSPDFDrawInputMethodMouse(4);

  final int value;
  const PSPDFDrawInputMethod(this.value);

  static PSPDFDrawInputMethod fromValue(int value) => switch (value) {
    0 => PSPDFDrawInputMethodNone,
    1 => PSPDFDrawInputMethodFinger,
    2 => PSPDFDrawInputMethodApplePencil,
    3 => PSPDFDrawInputMethodThirdPartyStylus,
    4 => PSPDFDrawInputMethodMouse,
    _ => throw ArgumentError('Unknown value for PSPDFDrawInputMethod: $value'),
  };
}

