  static const PSPDFFlexibleToolbarPositionRight = 4;

  /// The toolbar is positioned at the top, below the navigation bar.
  static const PSPDFFlexibleToolbarPositionTop = 8;

  /// All positions where the toolbar buttons are stacked horizontally. The toolbar can be positioned in the navigation bar or below it.
  static const PSPDFFlexibleToolbarPositionHorizontal = 9;

  /// All positions where the toolbar buttons are stacked vertically. The toolbar can be positioned on the left or right side of the available screen real estate.
  static const PSPDFFlexibleToolbarPositionVertical = 6;

  /// The default toolbar positions in the top (navigation)bar and on the left and right side of the available screen real estate.
  static const PSPDFFlexibleToolbarPositionDefault = 7;

  /// All valid toolbar positions. Excluding `PSPDFFlexibleToolbarPositionNone`.
  static const PSPDFFlexibleToolbarPositionAll = 15;
}

