  /// The view controller could not load or parse the manifest file.
  PSPDFGalleryViewControllerStateError(3);

  final int value;
  const PSPDFGalleryViewControllerState(this.value);

  static PSPDFGalleryViewControllerState fromValue(int value) =>
      switch (value) {
        0 => PSPDFGalleryViewControllerStateIdle,
        1 => PSPDFGalleryViewControllerStateLoading,
        2 => PSPDFGalleryViewControllerStateReady,
        3 => PSPDFGalleryViewControllerStateError,
        _ => throw ArgumentError(
          'Unknown value for PSPDFGalleryViewControllerState: $value',
        ),
      };
}

