  PSPDFIdleTimerManagementExtendedTime(1),

  /// Like `PSPDFIdleTimerManagementExtendedTime` but also keeps screen always on when a non-interactive external screen is connected. E.g. AirPlay to a TV.
  PSPDFIdleTimerManagementExtendedTimeExternalScreenDisablesTimer(2),

  /// Keeps screen awake as long as `PDFViewController` is on screen.
  PSPDFIdleTimerManagementDisablesTimer(3);

