    3 => PSPDFLineEndTypeDiamond,
    4 => PSPDFLineEndTypeOpenArrow,
    5 => PSPDFLineEndTypeClosedArrow,
    6 => PSPDFLineEndTypeButt,
    7 => PSPDFLineEndTypeReverseOpenArrow,
    8 => PSPDFLineEndTypeReverseClosedArrow,
    9 => PSPDFLineEndTypeSlash,
    _ => throw ArgumentError('Unknown value for PSPDFLineEndType: $value'),
  };
