        2 => PSPDFMediaPlayerControllerContentStateReady,
        3 => PSPDFMediaPlayerControllerContentStateError,
        _ => throw ArgumentError(
          'Unknown value for PSPDFMediaPlayerControllerContentState: $value',
        ),
      };
}

