/// An angle a PDF page is displayed at in clockwise degrees.
enum PSPDFRotation {
  /// The page is displayed without rotation.
  PSPDFRotation0(0),

  /// The page is displayed 90 degrees clockwise.
  PSPDFRotation90(90),

  /// The page is displayed upside-down.
  PSPDFRotation180(180),

  /// The page is displayed 90 degrees counterclockwise.
  PSPDFRotation270(270);

  final int value;
  const PSPDFRotation(this.value);

  static PSPDFRotation fromValue(int value) => switch (value) {
    0 => PSPDFRotation0,
    90 => PSPDFRotation90,
    180 => PSPDFRotation180,
    270 => PSPDFRotation270,
    _ => throw ArgumentError('Unknown value for PSPDFRotation: $value'),
  };
}

