/// Defines where the scrubber but should be shown.
enum PSPDFScrubberBarType {
  /// The default style: A scrubber bar that lays out its thumbnails along its width.
  PSPDFScrubberBarTypeHorizontal(0),

  /// Style for a scrubber bar that lays out its thumbnails along its height and sits along the left edge of its container.
  /// (I.e. it draws a border on its _right–hand_ side.)
  PSPDFScrubberBarTypeVerticalLeft(1),

  /// Style for a scrubber bar that lays out its thumbnails along its height and sits along the right edge of its container view.
  /// (I.e. it draws a border on its _left–hand_ side.)
  PSPDFScrubberBarTypeVerticalRight(2);

  final int value;
  const PSPDFScrubberBarType(this.value);

  static PSPDFScrubberBarType fromValue(int value) => switch (value) {
    0 => PSPDFScrubberBarTypeHorizontal,
    1 => PSPDFScrubberBarTypeVerticalLeft,
    2 => PSPDFScrubberBarTypeVerticalRight,
    _ => throw ArgumentError('Unknown value for PSPDFScrubberBarType: $value'),
  };
}

/// Visibility options for positioning the search bar.
enum PSPDFSearchBarPinning {
  /// The search bar will be pinned to the top of the view, unless in a popover presentation,
  /// in which case the search bar will scroll with the search results. This is the default.
  PSPDFSearchBarPinningAuto(0),

  /// The search bar will be displayed at the top of the view like a navigation bar.
  PSPDFSearchBarPinningTop(1),

  /// The search bar will be embedded inside the table view so it scrolls of the top when scrolling down through the search results.
  PSPDFSearchBarPinningNone(2),

  /// Hide the search bar completely. This is useful if a toolbar shows a full search bar instead of only a search button.
  PSPDFSearchBarPinningHidden(3);

  final int value;
  const PSPDFSearchBarPinning(this.value);

  static PSPDFSearchBarPinning fromValue(int value) => switch (value) {
    0 => PSPDFSearchBarPinningAuto,
    1 => PSPDFSearchBarPinningTop,
    2 => PSPDFSearchBarPinningNone,
    3 => PSPDFSearchBarPinningHidden,
    _ => throw ArgumentError('Unknown value for PSPDFSearchBarPinning: $value'),
  };
}

