enum PSPDFSearchStatus {
  /// Search hasn't started yet.
  PSPDFSearchStatusIdle(0),

  /// Search operation is running.
  PSPDFSearchStatusActive(1),

  /// Search has been finished.
  PSPDFSearchStatusFinished(2),

  /// Search finished but there wasn't any content to search.
  PSPDFSearchStatusFinishedNoText(3),

  /// Search has been cancelled.
  PSPDFSearchStatusCancelled(4);

  final int value;
  const PSPDFSearchStatus(this.value);

  static PSPDFSearchStatus fromValue(int value) => switch (value) {
    0 => PSPDFSearchStatusIdle,
    1 => PSPDFSearchStatusActive,
    2 => PSPDFSearchStatusFinished,
    3 => PSPDFSearchStatusFinishedNoText,
    4 => PSPDFSearchStatusCancelled,
    _ => throw ArgumentError('Unknown value for PSPDFSearchStatus: $value'),
  };
}

