  /// Show the signature appearance stream set in `signatureWatermark` only.
  PSPDFSignatureAppearanceModeSignatureOnly(2);

  final int value;
  const PSPDFSignatureAppearanceMode(this.value);

  static PSPDFSignatureAppearanceMode fromValue(int value) => switch (value) {
    0 => PSPDFSignatureAppearanceModeSignatureAndDescription,
    1 => PSPDFSignatureAppearanceModeDescriptionOnly,
    2 => PSPDFSignatureAppearanceModeSignatureOnly,
    _ => throw ArgumentError(
      'Unknown value for PSPDFSignatureAppearanceMode: $value',
    ),
  };
}

