/// The supported encryption algorithms that can be used when signing a document.
enum PSPDFSignatureEncryptionAlgorithm {
  /// RSA, one of the most popular public-key encryption systems.
  PSPDFSignatureEncryptionAlgorithmRSA(0),

  /// DSA (Digital Signature Algorithm). Faster than RSA for signing a document, but the verification is slower.
  PSPDFSignatureEncryptionAlgorithmDSA(1),

  /// ECDSA (Elliptic Curve Digital Signature Algorithm). Introduced for signing PDF documents in PDF 2.0.
  PSPDFSignatureEncryptionAlgorithmECDSA(2),

  /// This is an algorithm we don't currently know about.
  PSPDFSignatureEncryptionAlgorithmUnknown(3);

  final int value;
  const PSPDFSignatureEncryptionAlgorithm(this.value);

  static PSPDFSignatureEncryptionAlgorithm fromValue(int value) =>
      switch (value) {
        0 => PSPDFSignatureEncryptionAlgorithmRSA,
        1 => PSPDFSignatureEncryptionAlgorithmDSA,
        2 => PSPDFSignatureEncryptionAlgorithmECDSA,
        3 => PSPDFSignatureEncryptionAlgorithmUnknown,
        _ => throw ArgumentError(
          'Unknown value for PSPDFSignatureEncryptionAlgorithm: $value',
        ),
      };
}

