  static PSPDFSignatureStatusSeverity fromValue(int value) => switch (value) {
    0 => PSPDFSignatureStatusSeverityNone,
    1 => PSPDFSignatureStatusSeverityWarning,
    2 => PSPDFSignatureStatusSeverityError,
    _ => throw ArgumentError(
      'Unknown value for PSPDFSignatureStatusSeverity: $value',
    ),
  };
}

