/// The signature type defines the digital signature format that will be used to sign the document.
///
/// See https://www.nutrient.io/guides/ios/features/digital-signatures/
enum PSPDFSignatureType {
  /// CMS is a basic signature type and will work for most common situations.
  /// This translates to PDF `SubFilter` value of `adbe.pkcs7.detached`.
  PSPDFSignatureTypeCMS(0),

  /// PAdES is an advanced digital signature type with support for long term validation (LTV).
  /// This translates to PDF `SubFilter` value of `ETSI.CAdES.detached`.
  PSPDFSignatureTypePades(1),

  /// Deprecated. SHA1 is an older signature type which has been deprecated in PDF 2.0.
  /// We are not able to sign documents using this type, but it can be checked on validation.
  /// This translates to PDF `SubFilter` value of `adbe.pkcs7.sha1`.
  PSPDFSignatureTypeSHA1(2),

  /// An ETSI_RFC3161 document timestamp signature. Note that this is
  /// not the same as a signature (`.CMS` or `.pades`) with a
  /// timestamp. An RFC3161 document timestamp signature is a special
  /// kind of signature where the timestamp itself fills the entire
  /// signature, it doesn't require passing any additional
  /// certificates.
  PSPDFSignatureTypeTimestamp(3),

  /// Signature type could not be determined.
  PSPDFSignatureTypeUnknown(4);

  final int value;
  const PSPDFSignatureType(this.value);

  static PSPDFSignatureType fromValue(int value) => switch (value) {
    0 => PSPDFSignatureTypeCMS,
    1 => PSPDFSignatureTypePades,
    2 => PSPDFSignatureTypeSHA1,
    3 => PSPDFSignatureTypeTimestamp,
    4 => PSPDFSignatureTypeUnknown,
    _ => throw ArgumentError('Unknown value for PSPDFSignatureType: $value'),
  };
}

