  /// A problem occurred while adding the signature to the PKCS#7.
  PSPDFSignerErrorCannotNotAddSignatureToPKCS7(257),

  /// A problem occurred while initializing the PKCS#7 structure.
  PSPDFSignerErrorCannotNotInitPKCS7(258),

  /// An error occurred while generating the PKCS#7 signature.
  PSPDFSignerErrorCannotGeneratePKCS7Signature(259),

  /// A problem occurred while writing the PKCS#7 signature to the document.
  PSPDFSignerErrorCannotWritePKCS7Signature(260),

  /// The document was signed correctly but couldn't be verified afterwards.
  PSPDFSignerErrorCannotVerifySignature(261),

  /// The signed document could not be created. Check that you have the necessary permissions for the destination folder.
  PSPDFSignerErrorCannotSaveToDestination(262),

  /// The sub-filter type specified to create the signature is not supported.
  PSPDFSignerErrorUnsupportedSubfilterType(263),

  /// Cannot find the signature, either in a new or existing document.
  PSPDFSignerErrorCannotFindSignature(264),

  /// The attributes could not be signed.
  PSPDFSignerErrorCannotSignAttributes(265),

  /// The form element could not be signed.
  PSPDFSignerErrorCannotSignFormElement(272),

  /// The form element is already digitally signed, so it does not make sense to digitally sign it again.
  PSPDFSignerErrorCannotSignAlreadySigned(273),

  /// The byte range of the document could not be hashed.
  PSPDFSignerErrorCouldNotHashDocument(274),

  /// The certificate chain used to sign the document doesn't contain any certificate.
  PSPDFSignerErrorEmptyCertificateChain(275);

  final int value;
  const PSPDFSignerErrorCode(this.value);

  static PSPDFSignerErrorCode fromValue(int value) => switch (value) {
    0 => PSPDFSignerErrorNone,
    1 => PSPDFSignerErrorNoFormElementSet,
    256 => PSPDFSignerErrorCannotNotCreatePKCS7,
    257 => PSPDFSignerErrorCannotNotAddSignatureToPKCS7,
    258 => PSPDFSignerErrorCannotNotInitPKCS7,
    259 => PSPDFSignerErrorCannotGeneratePKCS7Signature,
    260 => PSPDFSignerErrorCannotWritePKCS7Signature,
    261 => PSPDFSignerErrorCannotVerifySignature,
    262 => PSPDFSignerErrorCannotSaveToDestination,
    263 => PSPDFSignerErrorUnsupportedSubfilterType,
    264 => PSPDFSignerErrorCannotFindSignature,
    265 => PSPDFSignerErrorCannotSignAttributes,
    272 => PSPDFSignerErrorCannotSignFormElement,
    273 => PSPDFSignerErrorCannotSignAlreadySigned,
    274 => PSPDFSignerErrorCouldNotHashDocument,
