}

/// Sound annotation recording and playback states.
enum PSPDFSoundAnnotationState {
  /// Stopped state.
  PSPDFSoundAnnotationStateStopped(0),

  /// Recording state.
  PSPDFSoundAnnotationStateRecording(1),

  /// Recording paused state.
  PSPDFSoundAnnotationStateRecordingPaused(2),

  /// Recording finished state.
  PSPDFSoundAnnotationStateRecordingFinished(3),

  /// Playing state.
  PSPDFSoundAnnotationStatePlaying(4),

  /// Playing paused state.
  PSPDFSoundAnnotationStatePlaybackPaused(5);

  final int value;
  const PSPDFSoundAnnotationState(this.value);

  static PSPDFSoundAnnotationState fromValue(int value) => switch (value) {
    0 => PSPDFSoundAnnotationStateStopped,
    1 => PSPDFSoundAnnotationStateRecording,
    2 => PSPDFSoundAnnotationStateRecordingPaused,
    3 => PSPDFSoundAnnotationStateRecordingFinished,
    4 => PSPDFSoundAnnotationStatePlaying,
    5 => PSPDFSoundAnnotationStatePlaybackPaused,
    _ => throw ArgumentError(
      'Unknown value for PSPDFSoundAnnotationState: $value',
    ),
  };
}

