enum PSPDFStatefulViewState {
  /// Controller is querying data.
  PSPDFStatefulViewStateLoading(0),

  /// Controller finished loading, has no data.
  PSPDFStatefulViewStateEmpty(1),

  /// Controller has data.
  PSPDFStatefulViewStateFinished(2);

  final int value;
  const PSPDFStatefulViewState(this.value);

  static PSPDFStatefulViewState fromValue(int value) => switch (value) {
    0 => PSPDFStatefulViewStateLoading,
    1 => PSPDFStatefulViewStateEmpty,
    2 => PSPDFStatefulViewStateFinished,
    _ => throw ArgumentError(
      'Unknown value for PSPDFStatefulViewState: $value',
    ),
  };
}

