/// Flags for submit-form actions. The names and behaviors of these flags are taken from the PDF reference.
///
/// If none of the format flags `.exportFormat`, `.xfdf`, and `.submitPDF` are specified then the format will be FDF.
/// For FDF, the `Content-Type` header field will incorrectly be `application/vnd.adobe.xfdf`. Please contact us if you require the correct type to be used (`application/vnd.fdf`).
sealed class PSPDFSubmitFormActionFlag {
  static const PSPDFSubmitFormActionFlagIncludeExclude = 1;
  static const PSPDFSubmitFormActionFlagIncludeNoValueFields = 2;

  /// Whether to submit the form like a URL query string (as an HTML form would be submitted). This is ignored if `.xfdf` or `.submitPDF` is set.
  static const PSPDFSubmitFormActionFlagExportFormat = 4;

  /// Whether to use the HTTP GET method instead of the HTTP POST method.
  ///
  /// Not supported.
  static const PSPDFSubmitFormActionFlagGetMethod = 8;
  static const PSPDFSubmitFormActionFlagSubmitCoordinates = 16;

  /// Whether to submit the form as XFDF. This takes precedence over `.exportFormat`, but it is ignored if `.submitPDF` is set.
  ///
  /// The `Content-Type` header field will incorrectly be `application/vnd.fdf`. Please contact us if you require the correct type to be used (`application/vnd.adobe.xfdf`).
  static const PSPDFSubmitFormActionFlagXFDF = 32;
  static const PSPDFSubmitFormActionFlagIncludeAppendSaves = 64;
  static const PSPDFSubmitFormActionFlagIncludeAnnotations = 128;

  /// Whether to submit the whole PDF rather than extracting form field values. This takes precedence over `.exportFormat` and `.xfdf`.
  static const PSPDFSubmitFormActionFlagSubmitPDF = 256;
  static const PSPDFSubmitFormActionFlagCanonicalFormat = 512;
  static const PSPDFSubmitFormActionFlagExclNonUserAnnots = 1024;
  static const PSPDFSubmitFormActionFlagExclFKey = 2048;
  static const PSPDFSubmitFormActionFlagEmbedForm = 8192;
}

/// The possible formats a form submission can be encoded in.
enum PSPDFSubmitFormActionFormat {
  /// The form will be submitted in Forms Data Format.
  PSPDFSubmitFormActionFormatFDF(0),

  /// The form will be submitted in XML Forms Data Format.
  PSPDFSubmitFormActionFormatXFDF(1),

  /// The form will be submitted in Hypertext Markup Language.
  PSPDFSubmitFormActionFormatHTML(2),

  /// The form will be submitted in Portable Document Format.
  PSPDFSubmitFormActionFormatPDF(3);

  final int value;
  const PSPDFSubmitFormActionFormat(this.value);

