  const PSPDFTabbedViewControllerCloseMode(this.value);

  static PSPDFTabbedViewControllerCloseMode fromValue(int value) =>
      switch (value) {
        0 => PSPDFTabbedViewControllerCloseModeOnlySelectedTab,
        1 => PSPDFTabbedViewControllerCloseModeAllTabs,
        2 => PSPDFTabbedViewControllerCloseModeSizeDependent,
        3 => PSPDFTabbedViewControllerCloseModeDisabled,
        _ => throw ArgumentError(
          'Unknown value for PSPDFTabbedViewControllerCloseMode: $value',
