/// Defines what happens when tapping.
enum PSPDFTapAction {
  /// Nothing happens.
  PSPDFTapActionNone(0),

  /// Zoom to the center of the user's tap.
  PSPDFTapActionZoom(1),

  /// Detect text blocks and zoom to the tapped text block.
  PSPDFTapActionSmartZoom(2);

  final int value;
  const PSPDFTapAction(this.value);

  static PSPDFTapAction fromValue(int value) => switch (value) {
    0 => PSPDFTapActionNone,
    1 => PSPDFTapActionZoom,
    2 => PSPDFTapActionSmartZoom,
    _ => throw ArgumentError('Unknown value for PSPDFTapAction: $value'),
  };
}

