  /// If specified, ignores case. Can be combined with any other option.
  static const PSPDFTextComparisonOptionCaseInsensitive = 1;

  /// If specified, ignores diacritics (o-umlaut == o). Can be combined with any other option.
  static const PSPDFTextComparisonOptionDiacriticInsensitive = 2;

  /// If specified, ignores width differences ('a' == UFF41). Can be combined with case or diacritic insensitivity. Implicitly disabled if you specify `.regularExpression` or `.smart`.
  static const PSPDFTextComparisonOptionWidthInsensitive = 4;

  /// If specified, hyphenations and newlines between the body text will be ignored. Enables search for typographic quotes/apostrophes as well. Can’t be combined with `.widthInsensitive` or `regularExpression`.
  static const PSPDFTextComparisonOptionSmart = 8;

  /// If specified, regular expression search will be enabled. Can’t be combined with `.widthInsensitive` or `.smart`.
  static const PSPDFTextComparisonOptionRegularExpression = 16;
}

