    0 => PSPDFTextInputFormatNormal,
    1 => PSPDFTextInputFormatNumber,
    2 => PSPDFTextInputFormatDate,
    3 => PSPDFTextInputFormatTime,
    _ => throw ArgumentError('Unknown value for PSPDFTextInputFormat: $value'),
  };
}

