/// The thumbnail bar mode controls how the `PDFViewController` displays thumbnails
/// of pages when viewing a document.
enum PSPDFThumbnailBarMode {
  /// Don't show any thumbnails.
  PSPDFThumbnailBarModeNone(0),

  /// Show scrubber bar (like Apple Books, `ScrubberBar`)
  PSPDFThumbnailBarModeScrubberBar(1),

  /// Show scrollable thumbnail bar (`ThumbnailBar`)
  PSPDFThumbnailBarModeScrollable(2),

  /// Show a floating scrubber bar (`ScrubberBar`)
  PSPDFThumbnailBarModeFloatingScrubberBar(3);

  final int value;
  const PSPDFThumbnailBarMode(this.value);

  static PSPDFThumbnailBarMode fromValue(int value) => switch (value) {
    0 => PSPDFThumbnailBarModeNone,
    1 => PSPDFThumbnailBarModeScrubberBar,
    2 => PSPDFThumbnailBarModeScrollable,
    3 => PSPDFThumbnailBarModeFloatingScrubberBar,
    _ => throw ArgumentError('Unknown value for PSPDFThumbnailBarMode: $value'),
  };
}

