/// Possible units for distances on a document page. These are used with the `from` value in a `MeasurementScale` object.
enum PSPDFUnitFrom {
  /// Inches (default). 1 inch is 72 PDF points.
  PSPDFUnitFromInch(0),

  /// Millimeters
  PSPDFUnitFromMillimeter(1),

  /// Centimeters
  PSPDFUnitFromCentimeter(2),

  /// PDF points. A PDF point is 1/72 inch. All values in a PDF page coordinate space (e.g. an annotation’s bounding box) are specified in PDF points.
  PSPDFUnitFromPoint(3);

  final int value;
  const PSPDFUnitFrom(this.value);

  static PSPDFUnitFrom fromValue(int value) => switch (value) {
    0 => PSPDFUnitFromInch,
    1 => PSPDFUnitFromMillimeter,
    2 => PSPDFUnitFromCentimeter,
    3 => PSPDFUnitFromPoint,
    _ => throw ArgumentError('Unknown value for PSPDFUnitFrom: $value'),
  };
}

/// Possible units for real world distances. These are used with the `to` value in a `MeasurementScale` object.
enum PSPDFUnitTo {
  /// Inches (default)
  PSPDFUnitToInch(0),

  /// Millimeters
  PSPDFUnitToMillimeter(1),

  /// Centimeters
  PSPDFUnitToCentimeter(2),

  /// Feet
  PSPDFUnitToFoot(4),

  /// Meters
  PSPDFUnitToMeter(5),

  /// Yards
  PSPDFUnitToYard(6),

  /// Kilometers
  PSPDFUnitToKilometer(7),

  /// Miles
  PSPDFUnitToMile(8);

  final int value;
  const PSPDFUnitTo(this.value);

  static PSPDFUnitTo fromValue(int value) => switch (value) {
    0 => PSPDFUnitToInch,
    1 => PSPDFUnitToMillimeter,
    2 => PSPDFUnitToCentimeter,
    4 => PSPDFUnitToFoot,
    5 => PSPDFUnitToMeter,
    6 => PSPDFUnitToYard,
    7 => PSPDFUnitToKilometer,
    8 => PSPDFUnitToMile,
    _ => throw ArgumentError('Unknown value for PSPDFUnitTo: $value'),
  };
}

