/// Defines how the user interface view should animate.
enum PSPDFUserInterfaceViewAnimation {
  /// Don't animate user interface view appearance.
  PSPDFUserInterfaceViewAnimationNone(0),

  /// Fade user interface view in/out.
  PSPDFUserInterfaceViewAnimationFade(1),

  /// Slide user interface view.
  PSPDFUserInterfaceViewAnimationSlide(2);

  final int value;
  const PSPDFUserInterfaceViewAnimation(this.value);

  static PSPDFUserInterfaceViewAnimation fromValue(int value) =>
      switch (value) {
        0 => PSPDFUserInterfaceViewAnimationNone,
        1 => PSPDFUserInterfaceViewAnimationFade,
        2 => PSPDFUserInterfaceViewAnimationSlide,
        _ => throw ArgumentError(
          'Unknown value for PSPDFUserInterfaceViewAnimation: $value',
        ),
