/// Current active view mode.
enum PSPDFViewMode {
  /// Document is visible.
  PSPDFViewModeDocument(0),

  /// Thumbnails are visible.
  PSPDFViewModeThumbnails(1),

  /// Shows thumbnails and page editing options.
  PSPDFViewModeDocumentEditor(2),

  /// Document is visible in content editing mode.
  ///
  /// > Important: Entering this view mode requires the _Content Editing_
  /// > feature to be included in your license.
  PSPDFViewModeContentEditing(3);

  final int value;
  const PSPDFViewMode(this.value);

  static PSPDFViewMode fromValue(int value) => switch (value) {
    0 => PSPDFViewModeDocument,
    1 => PSPDFViewModeThumbnails,
    2 => PSPDFViewModeDocumentEditor,
    3 => PSPDFViewModeContentEditing,
    _ => throw ArgumentError('Unknown value for PSPDFViewMode: $value'),
  };
}

